def score_state(state):
    n_lanes = len(state)
    n_slots = len(state[0]) if state else 0
    total_loads = sum(value > 0 for lane in state for value in lane)
    load_frequency = {}

    # Calculate frequency of each load type
    for lane in state:
        for value in lane:
            if value > 0:
                load_frequency[value] = load_frequency.get(value, 0) + 1

    score = 0

    for i in range(n_lanes):
        for j in range(n_slots):
            value = state[i][j]
            if value > 0:
                target_position = (value - 1) % n_slots
                depth_weight = (n_slots - j) / n_slots
                frequency_weight = load_frequency[value] / total_loads
                score += abs(j - target_position) * depth_weight * frequency_weight

    return  score

