def score_state(state):
    total_score = 0
    max_value = max(max(stack) for stack in state) if any(stack for stack in state) else 1

    for i in range(len(state)):
        stack = state[i]
        n = len(stack)

        for j in range(n - 1, -1, -1):
            load = stack[j]
            if load == 0:
                continue
            correct_pos_in_stack = next((k for k in range(j + 1, n) if stack[k] != 0 and load <= stack[k]), None)

            if correct_pos_in_stack is not None:
                position_penalty = (n - j) * (load / max_value)
                total_score += position_penalty
            else:
                min_distance_to_correct_order = float('inf')
                for k in range(len(state)):
                    if i == k:
                        continue
                    other_stack = state[k]
                    correct_pos_in_other_stack = next((l for l, val in enumerate(other_stack) if val != 0 and load <= val), None)
                    if correct_pos_in_other_stack is not None:
                        distance = len(stack) - j + correct_pos_in_other_stack + 1
                        min_distance_to_correct_order = min(min_distance_to_correct_order, distance)

                position_penalty = (min_distance_to_correct_order * (load / max_value)) ** 0.75
                total_score += position_penalty

    return  total_score

