            distance_penalty = abs(target_stack_idx - i) + (len(state[target_stack_idx]) - 1 - target_pos_in_stack)
            total_score += distance_penalty

            # Additional penalty for out-of-order loads within the stack
            if j > 0 and load < stack[j - 1]:
                out_of_order_penalty = load * 0.5
                total_score += out_of_order_penalty

