        if n == 0:
            continue

        # Calculate total moves needed to sort the stack
        sorted_stack = sorted(stack)
        move_count = sum(1 for i, j in zip(stack, sorted_stack) if i != j)

        # Calculate variance of the stack
        mean_value = sum(stack) / n if n > 0 else 0
        variance = sum((x - mean_value) ** 2 for x in stack) / n if n > 0 else 0

        for i in range(n):
            if i < n - 1 and stack[i] > stack[i + 1]:
                total_score += (i + 1) * stack[i] * move_count * (1 + variance)

