                else:
                    ordered_count += 1

        # Calculate the proportion of ordered items
        if ordered_count == 0:
            order_proportion = 0
        else:
            order_proportion = ordered_count / (ordered_count + out_of_order_count)

        # Penalize based on the number of out-of-order pairs and adjust by order proportion
        score += out_of_order_count * (1 - order_proportion)

    return  score

