def score_state(state):
    score = 0
    max_stack_height = max(len(stack) for stack in state)

    for stack in state:
        n = len(stack)
        if n == 0:
            continue

        total_out_of_order_count = 0
        total_value = 0

        for i in range(n - 1):
            if stack[i] > stack[i + 1]:
                total_out_of_order_count += 1
                total_value += (stack[i] + stack[i + 1])

        if total_out_of_order_count > 0:
            average_value = total_value / (total_out_of_order_count * 2)
            score += total_out_of_order_count * average_value * ((n - total_out_of_order_count) / max_stack_height)

    return  score

def score_state(state):
    total_score = 0
    for stack in state:
        n = len(stack)
        for i in range(n - 1):
            if stack[i] > stack[i + 1]:
                correct_order_distance = next((j - i for j in range(i + 1, n) if stack[j] != 0 and stack[i] > stack[j]), n - i)
                total_score += correct_order_distance ** 2
    return  total_score

def score_state(state):
    total_score = 0
    for stack in state:
        n = len(stack)
        stack_weight = 1 / (n if n > 0 else 1)  # Reduce penalty for larger stacks
        for i in range(n - 1):
            if stack[i] > stack[i + 1]:
                obstructing_loads_sum = sum(stack[j] for j in range(i + 1, n))
                total_score += (i + 1) * obstructing_loads_sum * stack_weight
    return  total_score

