def score_state(state):
    score = 0
    max_stack_height = max(len(stack) for stack in state)

    for stack in state:
        n = len(stack)
        sorted_stack = sorted(stack, reverse=True)

        for i in range(n - 1):
            for j in range(i + 1, n):
                if stack[i] > stack[j]:
                    correct_pos_i = sorted_stack.index(stack[i])
                    correct_pos_j = sorted_stack.index(stack[j])
                    position_penalty = abs(correct_pos_i - i) + abs(correct_pos_j - j)
                    weighted_penalty = position_penalty * (0.5 ** min(i, j))
                    score += weighted_penalty

    return  score

