def score_state(state):
    total_score = 0
    cross_stack_penalty_factor = 2.0  # Increased penalty for crossing stacks
    top_load_penalty_factor = 1.5     # Additional penalty for loads at the top

    for i in range(len(state)):
        stack = state[i]
        n = len(stack)
        inversions_count = sum(1 for j in range(n - 1) if stack[j] > stack[j + 1])
        inversion_penalty_factor = 1 + (inversions_count * 0.25) / max(1, n)  # Reduced inversion penalty factor

        for j in range(n - 1, -1, -1):
            if j == n - 1 and stack[j] != 0:
                total_score += stack[j] * top_load_penalty_factor
            if j > 0 and stack[j] < stack[j - 1]:
                correct_pos = next((k for k in range(j) if stack[k] != 0 and stack[j] <= stack[k]), j - 1)
                distance_penalty = (j - correct_pos) * stack[j]
                cross_stack_penalty = 0
                if correct_pos > j:
                    cross_stack_penalty = cross_stack_penalty_factor * stack[j]
                total_score += (distance_penalty + cross_stack_penalty) * inversion_penalty_factor

    return  total_score

