def score_state(state):
    score = 0
    target_positions = {}
    n_stacks = len(state)
    max_height = max(len(stack) for stack in state)

    # Determine target positions for each non-zero load
    current_target = 1
    for i in range(n_stacks):
        for j in range(max_height):
            if j < len(state[i]) and state[i][j] != 0:
                while current_target in target_positions.values():
                    current_target += 1
                target_positions[(i, j)] = current_target
                current_target += 1

    # Calculate the score based on distance to target positions
    for i in range(n_stacks):
        for j in range(max_height):
            if j < len(state[i]) and state[i][j] != 0:
                load_value = state[i][j]
                target_pos = [(ti, tj) for (ti, tj), val in target_positions.items() if val == load_value][0]
                distance = abs(i - target_pos[0]) + abs(j - target_pos[1])
                optimal_path_length = min(abs(target_pos[0] - n_stacks // 2), abs(target_pos[1] - max_height // 2))
                deviation_penalty = (distance - optimal_path_length) * load_value
                score += distance * load_value + deviation_penalty

    return  score

def score_state(state):
    total_score = 0
    for i, stack in enumerate(state):
        n = len(stack)
        stack_depth_factor = 1 / (n if n > 0 else 1)  # Adjust by inverse stack depth
        incorrect_positions_above = [0] * n
        for j in range(n - 2, -1, -1):
            if stack[j] > stack[j + 1]:
                incorrect_positions_above[j] = incorrect_positions_above[j + 1] + 1
        for j in range(n):
            total_score += (stack[j] * incorrect_positions_above[j]) * stack_depth_factor
    return  total_score

