        harmonic_mean_factor = (n / max_stack_height) if max_stack_height > 0 else 1

        for j in range(n - 1):
            if stack[j] > stack[j + 1]:
                correct_order_distance = next((k - j for k in range(j + 1, n) if stack[k] != 0 and stack[i] > stack[k]), n - j)
