def score_state(state):
    score = 0
    max_stack_height = max(len(stack) for stack in state)

    for stack in state:
        n = len(stack)
        sorted_stack = sorted(stack, reverse=True)

        for i in range(n - 1):
            for j in range(i + 1, n):
                if stack[i] > stack[j]:
                    correct_pos_i = sorted_stack.index(stack[i])
                    correct_pos_j = sorted_stack.index(stack[j])
                    distance_penalty = abs(correct_pos_i - i) + abs(correct_pos_j - j)
                    value_penalty = (stack[i] * stack[j]) ** 0.5
                    depth_factor = ((n - min(i, j)) / max_stack_height) ** 2
                    score += distance_penalty * value_penalty * depth_factor

    return  score

def score_state(state):
    score = 0
    max_stack_height = max(len(stack) for stack in state)

    for stack in state:
        n = len(stack)
        out_of_order_count = 0
        has_correct_pair = False

        for i in range(n - 1):
            if stack[i] > stack[i + 1]:
                out_of_order_count += 1
                score += (i + 1) * ((n - i) / max_stack_height)
            else:
                has_correct_pair = True

        if not has_correct_pair and n > 1:
            score += max_stack_height * 2

    return  score

def score_state(state):
    score = 0
    decay_factor = 1.5

    for i in range(len(state)):
        stack = state[i]
        n = len(stack)

        for j in range(n - 1, 0, -1):
            if stack[j] < stack[j - 1]:
                correct_pos = next((k for k in range(j) if stack[k] != 0 and stack[j] <= stack[k]), j - 1)
                distance_penalty = (j - correct_pos) * stack[j]
                score += distance_penalty * (decay_factor ** (n - j))

    return  score

def score_state(state):
