        for j in range(n - 1, 0, -1):
            if stack[j] < stack[j - 1]:
                distance_penalty = (n - j) * stack[j]
                cross_stack_penalty = 0
                for k in range(len(state)):
                    if k != i and any(stack[j] <= x for x in state[k]):
                        cross_stack_penalty = cross_stack_penalty_factor * stack[j]
                        break
                total_score += distance_penalty + cross_stack_penalty

    return  total_score

def score_state(state):
    total_score = 0
    cross_stack_penalty_factor = 1.5  # Additional penalty for crossing stacks
    max_stack_height = max(len(stack) for stack in state)

    for i, stack in enumerate(state):
        n = len(stack)
        for j in range(n - 1):
            if stack[j] > stack[j + 1]:
                correct_pos = None
                found = False
                for k in range(j + 1, len(state)):
                    if not found:
                        for l in range(len(state[k])):
                            if state[k][l] != 0 and stack[j] <= state[k][l]:
                                correct_pos = (k, l)
                                found = True
                                break

                if correct_pos is None:
                    continue

                k, l = correct_pos
                distance_penalty = abs(i - k) + abs(j - l) * stack[j]
                depth_weight = 1 - (j / max_stack_height)

                if i != k:
                    distance_penalty += cross_stack_penalty_factor * stack[j]

                total_score += distance_penalty * depth_weight

    return  total_score

def score_state(state):
    total_score = 0
    for i in range(len(state)):
        stack = state[i]
        n = len(stack)
        stack_height_factor = 1 / max(1, n)
        for j in range(n - 1):
            if stack[j] > stack[j + 1]:
                # Find the nearest correctly ordered load below the current out-of-order load
                correct_order_distance = next((k - j for k in range(j + 1, n) if stack[k] != 0 and stack[i] > stack[k]), n - j)
                total_score += (stack[j] * correct_order_distance) * stack_height_factor
    return  total_score

def score_state(state):
    total_score = 0
    cross_stack_penalty_factor = 1.5  # Additional penalty for crossing stacks
