        while current_index >= 0 and lane[current_index] != 0:
            if not expected or lane[current_index] < expected[-1]:
                expected.append(lane[current_index])
            current_index -= 1

        for load in lane:
            if load == 0:
                break
            target_position = len(expected) - expected.index(load) - 1 if load in expected else float('inf')
            score += abs(target_position - (len(lane) - lane[::-1].index(load)))

    return score

