def score_state(state):
    score = 0
    for lane in state:
        non_empty_start = next((i for i, x in enumerate(lane) if x != 0), len(lane))
        expected_value = 1
        for i in range(non_empty_start, len(lane)):
            if lane[i] < expected_value:
                score += (len(lane) - i)
            elif lane[i] > expected_value:
                score += (lane[i] - expected_value) * (len(lane) - i)
            expected_value = max(expected_value + 1, lane[i])
    return score

def score_state(state):
    score = 0.0
    for lane in state:
        max_priority = 0
        penalty_factor = 1
        for i, load in enumerate(lane):
            if load != 0:
                if load > max_priority:
                    max_priority = load
                elif load < max_priority:
                    # Calculate the distance to move this load to a non-blocking position
                    score += (len(lane) - i - 1) * penalty_factor
                penalty_factor += 1
    return score

def score_state(state):
    score = 0.0
    for lane in state:
        highest_priority = None
        for i in range(len(lane)):
            if lane[i] != 0:
                if highest_priority is not None and lane[i] < highest_priority:
                    score += (highest_priority - lane[i]) * (i + 1)
                highest_priority = lane[i]
    return score

def score_state(state):
    score = 0
    for lane in state:
        n = len(lane)
        for i in range(n):
            if lane[i] != 0:
                for j in range(i + 1, n):
                    if lane[j] != 0 and lane[i] > lane[j]:
                        score += (lane[i] - lane[j]) ** 2
    return score

def score_state(state):
    def calculate_penalty(lane):
        penalty = 0
        max_priority_seen = 0
        blocks = []
        for i in range(len(lane) - 1, -1, -1):
            if lane[i] == 0:
                break
            if lane[i] > max_priority_seen:
                max_priority_seen = lane[i]
            elif lane[i] < max_priority_seen:
                blocks.append((max_priority_seen, len(lane) - i))
        penalty += sum(position for _, position in blocks)
        return penalty

    score = sum(calculate_penalty(lane) for lane in state)
    return score

def score_state(state):
    score = 0
    for lane in state:
        non_zero_found = False
        distance = 0
        for load in lane:
            if load != 0:
                non_zero_found = True
                score += (distance * load)
                distance += 1
            elif non_zero_found:
                break
    return score

def score_state(state):
    score = 0.0
    for lane in state:
        for i in range(len(lane)):
            if lane[i] == 0:
                continue
            for j in range(i + 1, len(lane)):
                if lane[j] != 0 and lane[i] > lane[j]:
                    score += (5 - lane[j] + 1)
    return score

def score_state(state):
    score = 0.0
    for lane in state:
        max_priority_index = {}
        for i, load in enumerate(lane):
            if load != 0:
                if load not in max_priority_index or i > max_priority_index[load]:
                    max_priority_index[load] = i
        for priority in sorted(max_priority_index.keys()):
            score += max_priority_index[priority]
    return score

def score_state(state):
    score = 0.0
    max_distance = len(state[0]) if state else 0
    for lane in state:
        for i, load in enumerate(lane):
            if load != 0:
                # Calculate distance to goal position (innermost slot)
                distance_to_goal = max_distance - (i + 1)
                # Penalize higher priority loads more heavily
                score += (5 - load + 1) * distance_to_goal
    return score

def score_state(state):
    score = 0.0
    for lane in state:
        inversions = 0
        highest_priority_seen = float('inf')
        for load in reversed(lane):
            if load == 0:
                break
            if load < highest_priority_seen:
                highest_priority_seen = load
            elif load > highest_priority_seen:
                inversions += 1
        score += inversions * highest_priority_seen
    return score

def score_state(state):
    score = 0.0
    for lane in state:
        for i in range(len(lane)):
            for j in range(i + 1, len(lane)):
                if lane[i] != 0 and lane[j] != 0 and lane[i] > lane[j]:
                    score += 1
    return score

def score_state(state):
    score = 0.0
    for lane in state:
        n = len(lane)
        inversion_count = [0] * n
        for i in range(n):
            if lane[i] != 0:
                for j in range(i + 1, n):
                    if lane[j] != 0 and lane[i] > lane[j]:
                        inversion_count[i] += 1
        score += sum((n - i) * count for i, count in enumerate(inversion_count))
    return score

def score_state(state):
    score = 0
    for lane in state:
        n = len(lane)
        highest_priority_distance = [0] * 6  # To store the farthest distance each priority has moved
        for i in range(n):
            if lane[i] != 0:
                priority = lane[i]
                current_distance = n - i - 1
                if current_distance > highest_priority_distance[priority]:
                    score += (2 ** (priority - 1)) * (current_distance - highest_priority_distance[priority])
                    highest_priority_distance[priority] = current_distance
    return score

def score_state(state):
    score = 0.0
    for lane in state:
        highest_priority_seen = float('inf')
        for i in range(len(lane)):
            if lane[i] == 0:
