            if lane[i] > highest_priority_seen:
                score += (lane[i] * (i + 1))
            highest_priority_seen = min(highest_priority_seen, lane[i])
    return score

def score_state(state):
    score = 0
    for lane in state:
        non_empty_start = next((i for i, x in enumerate(lane) if x != 0), len(lane))
        sorted_lane = sorted(lane[non_empty_start:], reverse=True)
        for i in range(non_empty_start, len(lane)):
            if lane[i] != sorted_lane[i - non_empty_start]:
                score += (5 - lane[i]) * (len(lane) - i)
    return score

def score_state(state):
    score = 0.0
    for lane in state:
        penalties = [0] * len(lane)
        for i in range(len(lane)):
            if lane[i] != 0:
                for j in range(i + 1, len(lane)):
                    if lane[j] != 0 and lane[i] > lane[j]:
                        penalties[i] += (lane[i] - lane[j])
        score += sum(depth * penalty for depth, penalty in enumerate(penalties) if penalty > 0)
    return score

def score_state(state):
    score = 0
    for lane in state:
        max_depth = [0] * 6  # Since priority classes range from 1 to 5
        for i, load in enumerate(lane):
            if load != 0:
                for j in range(load + 1, 6):
                    score += (j - load) ** 2 * max_depth[j]
                max_depth[load] = max(max_depth[load], i + 1)
    return score

