def score_state(state):
    total_blocks = 0
    max_possible_blocks = 0

    for lane in state:
        non_empty_slots = [load for load in lane if load != 0]
        num_slots = len(non_empty_slots)
        max_possible_blocks += (num_slots * (num_slots - 1)) // 2

        for i in range(num_slots - 1):
            for j in range(i + 1, num_slots):
                if non_empty_slots[i] < non_empty_slots[j]:
                    total_blocks += 1

    if max_possible_blocks == 0:
        return 0.0

    score = total_blocks / max_possible_blocks
    return score

