def score_state(state):
    score = 0.0
    target_positions = {i: [] for i in range(1, 6)}  # Create a dictionary to store the target positions of each priority class

    for lane_idx, lane in enumerate(state):
        non_zero_elements = [load for load in lane if load != 0]
        for idx, load in enumerate(non_zero_elements):
            target_positions[load].append((lane_idx, idx))

    for priority in range(1, 6):
        positions = target_positions[priority]
        positions.sort(key=lambda x: (x[0], x[1]))  # Sort positions to determine the correct order

        for i in range(len(positions) - 1):
            if positions[i][0] == positions[i + 1][0]:  # Same lane
                score += abs(positions[i][1] - positions[i + 1][1])
            else:  # Different lanes
                score += len(state[positions[i][0]]) - positions[i][1] - 1 + positions[i + 1][1]

    return score

