    num_lanes = len(state)
    lane_lengths = [len(lane) - lane.count(0) for lane in state]
    max_lane_length = max(lane_lengths)

    # Sliding window penalty calculation
    for i in range(num_lanes):
        non_zero_elements = [load for load in state[i] if load != 0]
        n = len(non_zero_elements)
        blocked_indices = []
        for j in range(n - 1):
            if non_zero_elements[j] > non_zero_elements[j + 1]:
