        # Apply penalties based on blocking indices
        for idx in blocked_indices:
            penalty = (idx + 1) * non_zero_elements[idx]
            score += penalty

            # Check neighboring lanes for additional penalties
            for k in range(max(-1, i - 1), min(num_lanes, i + 2)):
                if k != i and lane_lengths[k] > idx:
                    neighbor_penalty = (idx + 1) * non_zero_elements[idx]
                    score += neighbor_penalty

        # Additional penalty for almost fully blocked lanes
        if n > 0 and len(blocked_indices) >= n // 2:
            score += max_lane_length - n

    return score

