def score_state(state):
    score = 0
    for lane in state:
        max_val = 0
        block_depth = 0
        cumulative_penalty = 0
        blocked_priorities = set()
        target_order = sorted(lane, key=lambda x: (x != 0, x))
        lane_length = len(lane)

        for idx, load in enumerate(lane):
            if load != 0:
                correct_idx = target_order.index(load)
                distance_to_target = abs(correct_idx - idx)
                if max_val > load:
                    block_depth += 1
                    penalty_factor = (block_depth * load) / lane_length * (1 / factorial(block_depth))
                    cumulative_penalty += (distance_to_target + penalty_factor)
                    blocked_priorities.add(load)
                else:
                    block_depth = 0
                max_val = load

        score += cumulative_penalty + len(blocked_priorities) * 2.0

    return score

def factorial(n):
    if n == 0 or n == 1:
        return 1
    result = 1
    for i in range(2, n + 1):
        result *= i
    return result

