        empty_slots = sum(1 for unit in lane if unit == 0)

        for unit in lane:
            if unit != 0:
                if unit < max_val:
                    block_count += 1
                    inversions += sum(1 for u in lane[lane.index(unit) + 1:] if u != 0 and u < unit)
                max_val = unit

        score += (block_count * 3) + (inversions * 2) + (empty_slots * 0.5)

    return score

def score_state(state):
    score = 0
    n_lanes = len(state)

    for lane in state:
        max_priority_seen = 0
        block_depth = 0
        misplaced_count = 0

        for idx, load in enumerate(lane):
            if load != 0:
                if max_priority_seen > load:
                    block_depth += 1
                    misplaced_count += block_depth * load
                else:
                    block_depth = 0
                max_priority_seen = load
                if idx > 0 and lane[idx] < lane[idx - 1]:
                    misplaced_count += load

        score += misplaced_count

    return score

def score_state(state):
    score = 0
    for lane in state:
        target_order = sorted(lane, key=lambda x: (x != 0, x))
        lane_length = len(lane)
        max_val = 0
        block_depth = 0

        for idx, load in enumerate(lane):
            if load != 0:
                correct_idx = target_order.index(load)
                distance_to_target = abs(correct_idx - idx)
                if max_val > load:
                    block_depth += 1
                    penalty_factor = (block_depth / lane_length) * (5 - load)
                    score += distance_to_target - penalty_factor
                else:
                    block_depth = 0
                max_val = load

    return score

def score_state(state):
    score = 0
    for lane in state:
        max_priority_seen = 0
        block_count = 0
        cumulative_penalty = 0
        for load in lane:
            if load != 0:
                if max_priority_seen > load:
                    block_count += 1
                    cumulative_penalty += (max_priority_seen - load) / max_priority_seen
                max_priority_seen = load
        # Additional penalty for distance from optimal position for highest priority items
        optimal_position_penalty = sum(1 for i, load in enumerate(lane) if load == 1 and i != len(lane) - 1)
        score += cumulative_penalty + block_count * 2 + optimal_position_penalty
    return score

def score_state(state):
    score = 0
    for lane in state:
        max_val = 0
        block_depth = 0
        blocked_priorities = set()
        lane_length = len(lane)

        for idx, load in enumerate(lane):
            if load != 0:
                if max_val > load:
                    block_depth += 1
                    score += (load * (block_depth ** 2)) / lane_length
                    blocked_priorities.add(load)
                else:
                    block_depth = 0
                max_val = load

        score += len(blocked_priorities) * 3

    return score

def score_state(state):
    score = 0
    weight_factor = 1.5  # Emphasize higher priority class blocks
    for lane in state:
        target_order = sorted(lane, key=lambda x: (x != 0, x))
        lane_length = len(lane)
        blocked_loads_count = 0
        max_blocked_priority = 0
        min_unblocked_priority = float('inf')

        for i, load in enumerate(lane):
            if load != 0:
                correct_load = target_order[i]
                if load != correct_load:
                    blocked_loads_count += 1
                    if lane[i] > max_blocked_priority:
                        max_blocked_priority = lane[i]
                    if lane[i] < min_unblocked_priority:
                        min_unblocked_priority = lane[i]

        if blocked_loads_count > 0:
            penalty_factor = (max_blocked_priority - min_unblocked_priority) / lane_length
            score += weight_factor * blocked_loads_count * penalty_factor + 2

    return score

def score_state(state):
    score = 0
    for lane in state:
        target_order = sorted(lane, key=lambda x: (x != 0, x))
        lane_length = len(lane)
        max_val = 0
        block_depth = 0

        for idx, load in enumerate(lane):
            if load != 0:
                correct_idx = target_order.index(load)
                distance_to_target = abs(correct_idx - idx)
                if max_val > load:
                    block_depth += 1
                    penalty_factor = (block_depth * (6 - load)) / lane_length
                    score += distance_to_target + penalty_factor
                else:
                    block_depth = 0
                max_val = load

    return score
